"""Verifier regression fixtures, generated by FFmpeg, never claimed as MAGIX output."""
import importlib.util
import pathlib
import tempfile
import unittest

from PIL import Image, ImageDraw

ROOT = pathlib.Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location('portal_demo_verifier', ROOT / 'tools/verify-portal-demo.py')
verifier = importlib.util.module_from_spec(spec)
spec.loader.exec_module(verifier)
FFMPEG = ROOT / '.build/ffmpeg/ffmpeg.exe'
FFPROBE = ROOT / '.build/ffmpeg/ffprobe.exe'
CLIP_A = ROOT / 'artifacts/direct-edit-test/Clip-A.avi'
CLIP_B = ROOT / 'artifacts/direct-edit-test/Clip-B.avi'


@unittest.skipUnless(all(path.is_file() for path in (FFMPEG, FFPROBE, CLIP_A, CLIP_B)), 'Portable FFmpeg and synthetic source clips are required.')
class PortalDemoVerifierTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        parent = ROOT / '.build/ffmpeg'
        cls.directory = pathlib.Path(tempfile.mkdtemp(prefix='verifier-fixtures-', dir=parent))
        cls.title = cls.directory / 'fixture-title.png'
        image = Image.new('RGBA', (640, 360), (0, 0, 0, 0))
        ImageDraw.Draw(image).text((320, 180), 'ED-IT Buddy', fill='white', anchor='mm', font_size=28)
        image.save(cls.title)
        cls.valid = cls.make_fixture('ffmpeg-only-valid-fixture.mp4')

    @classmethod
    def make_fixture(cls, name, wrong_order=False, wrong_trim=False, short=False):
        output = cls.directory / name
        b_start, b_end = (0, 90) if wrong_trim else (30, 120)
        order = '[b][a]' if wrong_order else '[a][b]'
        graph = f'[0:v]trim=start_frame=0:end_frame=60,setpts=PTS-STARTPTS[a];[1:v]trim=start_frame={b_start}:end_frame={b_end},setpts=PTS-STARTPTS[b];{order}concat=n=2:v=1:a=0[cut];[cut][2:v]overlay=enable=\'lt(t,2)\'[v]'
        command = [str(FFMPEG), '-v', 'error', '-nostdin', '-n', '-i', str(CLIP_A), '-i', str(CLIP_B), '-i', str(cls.title),
                   '-filter_complex', graph, '-map', '[v]', '-an', '-c:v', 'libx264', '-preset', 'ultrafast', '-crf', '18', '-pix_fmt', 'yuv420p', '-r', '30']
        if short:
            command += ['-t', '4']
        command += ['-metadata', 'comment=FFmpeg regression fixture; not created by MAGIX', str(output)]
        verifier.run(command)
        return output

    def inspect_fixture(self, path, output_name):
        return verifier.verify(path, self.directory / output_name, FFMPEG, FFPROBE, CLIP_A, CLIP_B,
                               'FFmpeg-generated regression fixture, NOT a MAGIX demonstration')

    def test_valid_edit_content_passes_but_title_and_project_remain_unverified(self):
        report = self.inspect_fixture(self.valid, 'valid-report')
        self.assertTrue(report['automated_media_pass'], report['failures'])
        self.assertEqual(report['decoded_frames'], 150)
        self.assertTrue(report['inputs_unchanged'])
        self.assertTrue(pathlib.Path(report['contact_sheet']).is_file())
        self.assertFalse(report['overall_demo_verified'])
        self.assertEqual(report['title_review']['status'], 'required')
        self.assertEqual(report['project_review']['status'], 'required')

    def test_reversed_clips_fail_content_checks(self):
        movie = self.make_fixture('ffmpeg-only-reversed-fixture.mp4', wrong_order=True)
        report = self.inspect_fixture(movie, 'reversed-report')
        self.assertFalse(report['automated_media_pass'])
        self.assertIn('clip_order_or_source_frames', report['failures'])

    def test_wrong_source_in_point_fails_even_with_right_duration_and_order(self):
        movie = self.make_fixture('ffmpeg-only-wrong-trim-fixture.mp4', wrong_trim=True)
        report = self.inspect_fixture(movie, 'wrong-trim-report')
        self.assertTrue(all(report['metadata_checks'].values()))
        self.assertFalse(report['automated_media_pass'])
        self.assertGreater(report['content_failed_frames'], 0)

    def test_short_video_fails_frame_count_and_duration(self):
        movie = self.make_fixture('ffmpeg-only-short-fixture.mp4', short=True)
        report = self.inspect_fixture(movie, 'short-report')
        self.assertFalse(report['automated_media_pass'])
        self.assertIn('metadata_frame_count', report['failures'])
        self.assertIn('metadata_duration', report['failures'])
        self.assertTrue(pathlib.Path(report['contact_sheet']).is_file())
        self.assertGreater(report['decoded_frames'], 0)
        self.assertIn('decoded_frame_count', report['failures'])

    def test_existing_output_directory_is_refused_and_sources_unchanged(self):
        output = self.directory / 'already-exists'
        output.mkdir()
        before = verifier.digest(self.valid)
        with self.assertRaises(FileExistsError):
            self.inspect_fixture(self.valid, output.name)
        self.assertEqual(verifier.digest(self.valid), before)

    @classmethod
    def tearDownClass(cls):
        # Retain clearly named fixtures and reports for inspection; never mix with real exports.
        print('Retained FFmpeg-only verifier fixtures:', cls.directory)


if __name__ == '__main__':
    unittest.main()
